// The reply rule in the contract gives the same verdict as the JS rule (tee/reply.mjs) on every shared case
// (tests/fixtures/reply-cases.json, generated by node certify/make-reply-cases.mjs). 7 Nov audit: the two had
// disagreed on duplicate keys, "12.0", unicode spaces and repeated code fences.
use near_sdk::serde_json::{self, Value};
use truenav_registry::reply_problem;

#[test]
fn every_shared_reply_case_matches_the_js_rule() {
    let fx: Value = serde_json::from_str(&std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/reply-cases.json")).unwrap()).unwrap();
    let cases = fx["cases"].as_array().unwrap();
    assert!(cases.len() >= 20);
    for c in cases {
        let body = c["body"].as_str().unwrap();
        let accept = c["accept"].as_bool().unwrap();
        assert_eq!(reply_problem(body).is_none(), accept, "{}: {:?}", c["name"], reply_problem(body));
    }
}
